python -I -c "
import numpy as np, pandas as pd
from scipy.optimize import curve_fit
def lor(x,a,x0,g): return a*(g/2)**2/((x-x0)**2+(g/2)**2)
def m_lin(x,a,x0,g,c0,c1): return lor(x,a,x0,g)+c0+c1*(x-1367)
def m_quad(x,a,x0,g,c0,c1,c2): return lor(x,a,x0,g)+c0+c1*(x-1367)+c2*(x-1367)**2
def fit(x,y,lo,hi,model,p0):
    m=(x>=lo)&(x<=hi); xs,ys=x[m],y[m]
    p,cov=curve_fit(model,xs,ys,p0=p0,maxfev=50000)
    return p,np.sqrt(np.diag(cov)),np.std(ys-model(xs,*p))
F={}
for f in ['spectrum_flake1.csv','spectrum_flake2.csv']:
    d=pd.read_csv(f); F[f]=(d.shift_cm1.values,d.intensity.values)
print('Robustness of hBN E2g fit (Lorentzian + baseline)')
for f in F:
    x,y=F[f]
    for lo,hi,mod,nm in [(1300,1440,m_lin,'lin'),(1320,1420,m_lin,'lin'),(1280,1460,m_quad,'quad'),(1340,1400,m_lin,'lin')]:
        p0=[1000,1367,15,1000,0] if mod is m_lin else [1000,1367,15,1000,0,0]
        try:
            p,e,s=fit(x,y,lo,hi,mod,p0)
            print('  %s win %d-%d %s: x0=%.2f+-%.2f FWHM=%.2f+-%.2f amp=%.0f  area=%.0f  resid=%.1f'%(f[9:15],lo,hi,nm,p[1],e[1],p[2],e[2],p[0],np.pi*p[0]*p[2]/2,s))
        except Exception as ex: print('  fit fail',ex)
print('Si top flatness (flake2): points 515-526 near max')
x,y=F['spectrum_flake2.csv']; m=(x>515)&(x<526)
for xi,yi in zip(x[m][::3],y[m][::3]): print('  %.2f %.0f'%(xi,yi))
print('Flake 1 candidate minor peaks: local SNR')
x,y=F['spectrum_flake1.csv']
for c in [466.4,1197.0]:
    m=(x>c-6)&(x<c+6); print('  near',c, [ (round(a,1),round(b)) for a,b in zip(x[m],y[m])])
"

